// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadAnton = makeLoadFont('Anton');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: antonFamily } = loadAnton();



export type WinnerRevealProps = Record<string, any>;

const WinnerReveal: React.FC<WinnerRevealProps> = ({
  backgroundColor = "#0f0f13",
  transparentBackground = false,
  durationInSeconds = 8,
  buildupText = "AND THE WINNER IS...",
  winnerText = "MALLOY STUDIO",
  winnerColor = "#FFD700",
  textColor = "#FFFFFF",
  particleColors = ["#FFD700", "#FF6B6B", "#4ECDC4", "#FFFFFF", "#FF00FF"],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // ---------------------------------------------------------------------------
  // PARSER SAFETY & BASE VARIABLES
  // ---------------------------------------------------------------------------
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Timing configuration
  const REVEAL_FRAME = 90; // Frame where the winner explodes onto screen
  const s = Math.min(width, height);

  // ---------------------------------------------------------------------------
  // ANIMATION LOGIC - PHASE 1: BUILDUP
  // ---------------------------------------------------------------------------
  // Fade in the buildup text
  const buildupOpacity = interpolate(frame, [10, 30], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Slowly expand letter spacing for tension
  const buildupTracking = interpolate(frame, [0, REVEAL_FRAME], [0, 25], {
    extrapolateRight: "clamp",
  });

  // When reveal hits, buildup text shoots up and shrinks
  const buildupY = spring({
    frame: Math.max(0, frame - REVEAL_FRAME),
    fps,
    config: { damping: 12, stiffness: 100 },
    from: 0,
    to: -height * 0.25,
  });

  const buildupScale = spring({
    frame: Math.max(0, frame - REVEAL_FRAME),
    fps,
    config: { damping: 12, stiffness: 100 },
    from: 1,
    to: 0.5,
  });

  const buildupFadeOut = interpolate(
    frame,
    [REVEAL_FRAME + 30, REVEAL_FRAME + 60],
    [1, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // ---------------------------------------------------------------------------
  // ANIMATION LOGIC - PHASE 2: REVEAL (WINNER TEXT)
  // ---------------------------------------------------------------------------
  const winnerScale = spring({
    frame: Math.max(0, frame - REVEAL_FRAME),
    fps,
    config: { damping: 10, mass: 1, stiffness: 120 },
    from: 0,
    to: 1,
  });

  // Continuous slow scale after the initial burst
  const winnerContinuousScale = interpolate(
    frame,
    [REVEAL_FRAME, REVEAL_FRAME + 150],
    [1, 1.1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const finalWinnerScale = winnerScale * winnerContinuousScale;

  // ---------------------------------------------------------------------------
  // ANIMATION LOGIC - PHASE 3: CONFETTI EXPLOSION
  // ---------------------------------------------------------------------------
  const gravity = 0.6;
  const confettiCount = 120;
  
  const confettiElements = Array.from({ length: confettiCount }).map((_, i) => {
    const seed = i;
    const localFrame = Math.max(0, frame - REVEAL_FRAME);

    if (localFrame === 0) return null;

    // Deterministic random physics properties based on seed
    const angle = random(`angle-${seed}`) * Math.PI * 2;
    const velocity = 15 + random(`vel-${seed}`) * 45;
    
    // Calculate position with gravity
    const xOffset = Math.cos(angle) * velocity * localFrame;
    const yOffset = (Math.sin(angle) * velocity * localFrame) + (0.5 * gravity * localFrame * localFrame);

    const size = s * 0.01 + random(`size-${seed}`) * (s * 0.02);
    const color = particleColors[Math.floor(random(`color-${seed}`) * particleColors.length)];
    const rotation = localFrame * (random(`rot-${seed}`) * 15 - 7.5);
    
    // Fade out particles towards the end of their life
    const opacity = interpolate(localFrame, [90, 140], [1, 0], {
      extrapolateRight: "clamp",
    });

    const isCircle = random(`shape-${seed}`) > 0.5;

    return (
      <div
        key={seed}
        style={{
          position: "absolute",
          left: width / 2,
          top: height / 2,
          width: size,
          height: size,
          backgroundColor: color,
          borderRadius: isCircle ? "50%" : "2px",
          opacity,
          transform: `translate(-50%, -50%) translate(${xOffset}px, ${yOffset}px) rotate(${rotation}deg)`,
          transition: "none",
        }}
      />
    );
  });

  // Flash background on reveal
  const flashOpacity = interpolate(
    frame,
    [REVEAL_FRAME, REVEAL_FRAME + 5],
    [0.8, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        overflow: "hidden",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      {/* Background Radial Gradient to focus center */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(circle at center, transparent 0%, rgba(0,0,0,0.6) 100%)`,
          transition: "none",
        }}
      />

      {/* Confetti Layer (Behind Text) */}
      {frame >= REVEAL_FRAME && confettiElements}

      {/* Buildup Text */}
      <div
        style={{
          position: "absolute",
          fontFamily: interFamily,
          fontSize: s * 0.06,
          fontWeight: 800,
          color: textColor,
          opacity: buildupOpacity * buildupFadeOut,
          transform: `translateY(${buildupY}px) scale(${buildupScale})`,
          letterSpacing: `${buildupTracking}px`,
          textAlign: "center",
          width: "80%",
          display: "flex",
          justifyContent: "center",
          transition: "none",
          textShadow: `0 4px 12px rgba(0,0,0,0.5)`,
        }}
      >
        {buildupText}
      </div>

      {/* Winner Reveal Text */}
      {frame >= REVEAL_FRAME && (
        <div
          style={{
            position: "absolute",
            fontFamily: antonFamily,
            fontSize: s * 0.25,
            lineHeight: 1.1,
            color: winnerColor,
            textAlign: "center",
            width: "90%",
            transform: `scale(${finalWinnerScale})`,
            transition: "none",
            textTransform: "uppercase",
            WebkitTextStroke: `4px ${textColor}`,
            textShadow: `
              0 10px 30px rgba(0,0,0,0.8),
              0 20px 60px ${winnerColor}40
            `,
          }}
        >
          {winnerText}
        </div>
      )}

      {/* Impact Flash */}
      {frame >= REVEAL_FRAME && frame <= REVEAL_FRAME + 5 && (
        <AbsoluteFill
          style={{
            backgroundColor: "#FFFFFF",
            opacity: flashOpacity,
            pointerEvents: "none",
            transition: "none",
          }}
        />
      )}
    </AbsoluteFill>
  );
};

export default WinnerReveal;